        waitFor("food-finished-and-consumed-natively",1600,()->state("recover",s->s.path("counters").path("nativeFoodConsumptions").asInt()>0).thenApply(ready->{if(ready&&playerActor()){var motion=NativeSkillInput.motionEvidence();require(((Number)motion.get("maxAimUpdatesPerTick")).intValue()==1,"MULTIPLE_COMPETING_AIM_UPDATES_"+motion);EVIDENCE.add(motion);}return ready;}));
