        action("till-and-plant-target",()->server(p->{p.level().setBlock(new BlockPos(3,100,12),Blocks.DIRT.defaultBlockState(),2);p.level().setBlock(new BlockPos(3,101,12),Blocks.AIR.defaultBlockState(),2);p.level().setBlock(new BlockPos(3,100,13),Blocks.WATER.defaultBlockState(),2);return null;}));
        action("native-till-and-replant",()->tool("farm_area",area("till","ai",3,101,12,3,101,12).put("repeat",false).put("crop","minecraft:wheat").put("till",true)));
        waitFor("native-till-effect",1200,()->state("till",s->s.path("state").asText().equals("COMPLETED")&&s.path("counters").path("tilled").asInt()==1&&s.path("counters").path("planted").asInt()==1));
