        action("pause-before-death",()->tool("control_behavior",JSON.createObjectNode().put("id","death_paused").put("expected_revision",1).put("action","pause")));
        action("native-death-while-manually-paused",()->server(p->{p.hurtServer(p.level(),p.damageSources().genericKill(),Float.MAX_VALUE);return null;}));
        waitFor("death-terminates-paused-skill",200,()->tool("inspect_behavior",JSON.createObjectNode()).thenApply(data->{var s=session(data,"death_paused");if(!s.path("state").asText().equals("CANCELLED"))return false;require(!AutonomousBodyClient.active(),"DEATH_LEFT_CLIENT_TAKEOVER_ACTIVE");EVIDENCE.add(data);return true;}));
